"""Assemble GLSL sources from a shared prelude generated by the Python schema.

The anchor codebook and channel layout exist in exactly one place,
:mod:`bds_format`. This module emits them as GLSL constants and injects them
into each shader stage, so the CPU and GPU views of a cell cannot drift.
"""

from __future__ import annotations

from pathlib import Path
from typing import Final

from bds_format import (
    ANCHORS,
    HUMAN_LOCK_CHANNEL,
    PRIORITY_CHANNEL,
    PRIORITY_LEVELS,
    VECTOR_DIMENSIONS,
)

SHADER_DIRECTORY: Final = Path(__file__).resolve().parent / "shaders"
PRELUDE_TOKEN: Final = "//#prelude"
MAX_COMMANDS_PER_TICK: Final = 64
COMMAND_FLOATS: Final = 8
WORKGROUP_SIZE: Final = 16
CLAMP_LIMIT: Final = 1.5
SNAP_THRESHOLD: Final = 1.5
EMPTY_EPSILON: Final = 0.01

COMPUTE_PASSES: Final[tuple[str, ...]] = ("physics", "semantic", "constraint")


def anchor_names() -> list[str]:
    return list(ANCHORS)


def priority_scale() -> float:
    """Normalization factor mapping a priority level onto ``[0, 1]``."""
    return 1.0 / float(max(PRIORITY_LEVELS.values()))


def normalize_priority(level: int) -> float:
    if level not in PRIORITY_LEVELS.values():
        raise ValueError(f"Unknown priority level: {level}")
    return level * priority_scale()


def generate_prelude() -> str:
    """Return the GLSL constants shared by every stage."""
    rows = ",\n".join(
        "    float[%d](%s)" % (
            VECTOR_DIMENSIONS,
            ", ".join(_format_float(value) for value in vector),
        )
        for vector in ANCHORS.values()
    )
    names = "".join(
        f"// anchor {index} = {name}\n" for index, name in enumerate(ANCHORS)
    )
    return f"""// Generated from bds_format.py; do not edit by hand.
const int CHANNELS = {VECTOR_DIMENSIONS};
const int ANCHOR_COUNT = {len(ANCHORS)};
const int PRIORITY_CHANNEL = {PRIORITY_CHANNEL};
const int HUMAN_LOCK_CHANNEL = {HUMAN_LOCK_CHANNEL};
const int MAX_COMMANDS = {MAX_COMMANDS_PER_TICK};
const float CLAMP_LIMIT = {_format_float(CLAMP_LIMIT)};
const float SNAP_THRESHOLD = {_format_float(SNAP_THRESHOLD)};
const float EMPTY_EPSILON = {_format_float(EMPTY_EPSILON)};

{names}const float ANCHOR_TABLE[ANCHOR_COUNT][CHANNELS] = float[ANCHOR_COUNT][CHANNELS](
{rows}
);

struct Cell {{
    float value[CHANNELS];
}};

struct PaintCommand {{
    vec4 segment;
    vec4 settings;
}};

float anchor_value(int anchor, int channel) {{
    return ANCHOR_TABLE[clamp(anchor, 0, ANCHOR_COUNT - 1)][channel];
}}

float group_norm(float state[CHANNELS], int group) {{
    float total = 0.0;
    int first = group * 8;
    for (int offset = 0; offset < 8; ++offset) {{
        float component = state[first + offset];
        total += component * component;
    }}
    return sqrt(total);
}}

float distance_to_segment(vec2 point, vec2 start, vec2 end) {{
    vec2 span = end - start;
    float length_squared = dot(span, span);
    if (length_squared < 1e-6) {{
        return length(point - start);
    }}
    float position = clamp(dot(point - start, span) / length_squared, 0.0, 1.0);
    return length(point - (start + position * span));
}}

bool is_locked(float state[CHANNELS]) {{
    return state[HUMAN_LOCK_CHANNEL] >= 0.5;
}}
"""


def load_shader(name: str) -> str:
    """Read a shader stage and expand its prelude token."""
    path = SHADER_DIRECTORY / name
    source = path.read_text(encoding="utf-8")
    if PRELUDE_TOKEN not in source:
        raise ValueError(f"{name} does not contain the {PRELUDE_TOKEN} token")
    return source.replace(PRELUDE_TOKEN, generate_prelude())


def load_compute_passes() -> dict[str, str]:
    """Return the assembled source for each compute stage, in execution order."""
    return {name: load_shader(f"{name}.comp") for name in COMPUTE_PASSES}


def _format_float(value: float) -> str:
    text = repr(float(value))
    return text if ("." in text or "e" in text or "E" in text) else f"{text}.0"


__all__ = [
    "PRELUDE_TOKEN",
    "CLAMP_LIMIT",
    "COMMAND_FLOATS",
    "COMPUTE_PASSES",
    "EMPTY_EPSILON",
    "MAX_COMMANDS_PER_TICK",
    "SHADER_DIRECTORY",
    "SNAP_THRESHOLD",
    "WORKGROUP_SIZE",
    "anchor_names",
    "generate_prelude",
    "load_compute_passes",
    "load_shader",
    "normalize_priority",
    "priority_scale",
]
